parameters.functionCode:
const trainingData = $json;

// Validate required fields
const requiredFields = ['model_type', 'training_images', 'model_name', 'user_id'];
const missingFields = requiredFields.filter(field => !trainingData[field]);

if (missingFields.length > 0) {
  throw new Error(`Missing required fields: ${missingFields.join(', ')}`);
}

// Validate image count and quality
if (trainingData.training_images.length < 10) {
  throw new Error('Minimum 10 training images required');
}

if (trainingData.training_images.length > 100) {
  throw new Error('Maximum 100 training images allowed');
}

// Validate model type
const supportedTypes = ['flux-lora', 'stable-diffusion-lora', 'custom-style'];
if (!supportedTypes.includes(trainingData.model_type)) {
  throw new Error(`Unsupported model type. Supported: ${supportedTypes.join(', ')}`);
}

return {
  valid: true,
  training_id: `training_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  model_type: trainingData.model_type,
  model_name: trainingData.model_name,
  user_id: trainingData.user_id,
  training_images: trainingData.training_images,
  estimated_cost: trainingData.training_images.length * 0.1, // $0.10 per image
  estimated_time: Math.ceil(trainingData.training_images.length / 10) * 30 // 30 min per 10 images
};

